#!/bin/bash
# gmRunner's feature tests: a GameMaker project (tests/gmtest/src, generated by make_project.py)
# whose scripts log what they observe as "name = value" lines.
#
#   tools/gmtest.sh                   build it with GameMaker's Igor, run it in gmRunner and compare
#                                     with tests/gmtest/reference.txt
#   tools/gmtest.sh --take-reference  copy the results of a run on GameMaker's own runner (open
#                                     tests/gmtest/gmtest/gmtest.yyp in the IDE and press Run first)
#                                     into tests/gmtest/reference.txt
#
# Needs GameMaker installed and signed in (Igor won't build otherwise); GMTEST_RUNTIME and
# GMTEST_USER point at the runtime and user folder when they aren't found by themselves.
set -eu
root="$(cd "$(dirname "$0")/.." && pwd)"
ref="$root/tests/gmtest/reference.txt"
work="$root/build/gmtest"

if [ "${1:-}" = "--take-reference" ]; then
    # GameMaker's macOS runner (Run in the IDE) writes to its own save area.
    got="$(ls -t "$HOME"/Library/Application\ Support/com.yoyogames.macyoyorunner/gmtest_results.txt \
              "$HOME"/Library/Application\ Support/*/gmtest_results.txt 2>/dev/null | head -1)"
    [ -n "$got" ] || { echo "no gmtest_results.txt from GameMaker found; run the project in the IDE first" >&2; exit 1; }
    cp "$got" "$ref"
    echo "reference: $got -> $ref ($(wc -l < "$ref" | tr -d ' ') results)"
    exit 0
fi

python3 "$root/tests/gmtest/make_project.py" >/dev/null
rm -rf "${work:?}"; mkdir -p "$work"
"$root/tools/gm-build.sh" "$root/tests/gmtest/gmtest/gmtest.yyp" "$work/game"

"$root/build/gmrunner" "$work/game" --hidden --fast --frames 120 --mute --save-dir "$work/save" \
    > "$work/gmrunner.log" 2>&1 || true
results="$work/save/gmtest_results.txt"
[ -f "$results" ] || { echo "gmRunner wrote no results; see $work/gmrunner.log" >&2; exit 1; }
if [ ! -f "$ref" ]; then
    echo "$(wc -l < "$results" | tr -d ' ') results in $results; no reference yet (tools/gmtest.sh --take-reference)"
    exit 0
fi
# The runtime line differs by design; everything else must match.
if diff <(grep -v '^runtime = ' "$ref") <(grep -v '^runtime = ' "$results") > "$work/diff.txt" 2>/dev/null; then
    echo "gmtest: all $(grep -vc '^runtime = ' "$ref") results match GameMaker"
else
    echo "gmtest: differences from GameMaker (< GameMaker, > gmRunner):"
    cat "$work/diff.txt"
    exit 1
fi
